package com.tradepilot.backtest.engine;
import com.tradepilot.backtest.model.BacktestBar; import java.math.*; import java.util.*;
public class DisplacementDetector { public Optional<Measurement> measure(List<BacktestBar> bars,int index,int lookback,BigDecimal bodyMultiplier,BigDecimal rangeMultiplier,BigDecimal closeThreshold){if(index<lookback)return Optional.empty();BacktestBar bar=bars.get(index);List<BigDecimal>bodies=new ArrayList<>(),ranges=new ArrayList<>();for(int i=index-lookback;i<index;i++){BacktestBar p=bars.get(i);if(p.instrumentId()!=bar.instrumentId())return Optional.empty();bodies.add(p.close().subtract(p.open()).abs());ranges.add(p.high().subtract(p.low()));}BigDecimal body=bar.close().subtract(bar.open()).abs(),range=bar.high().subtract(bar.low()),bodyMedian=median(bodies),rangeMedian=median(ranges);if(range.signum()==0)return Optional.empty();BigDecimal closeLocation=(bar.close().subtract(bar.low())).divide(range,6,RoundingMode.HALF_UP);boolean bullish=bar.close().compareTo(bar.open())>0&&closeLocation.compareTo(closeThreshold)>=0;boolean bearish=bar.close().compareTo(bar.open())<0&&BigDecimal.ONE.subtract(closeLocation).compareTo(closeThreshold)>=0;boolean qualifies=body.compareTo(bodyMedian.multiply(bodyMultiplier))>=0&&range.compareTo(rangeMedian.multiply(rangeMultiplier))>=0&&(bullish||bearish);return Optional.of(new Measurement(qualifies,bullish?Direction.BULLISH:bearish?Direction.BEARISH:Direction.NONE,body.divide(bodyMedian.max(new BigDecimal(".000001")),6,RoundingMode.HALF_UP),range.divide(rangeMedian.max(new BigDecimal(".000001")),6,RoundingMode.HALF_UP),closeLocation));}private BigDecimal median(List<BigDecimal> values){values.sort(BigDecimal::compareTo);return values.get(values.size()/2);} public enum Direction{BULLISH,BEARISH,NONE} public record Measurement(boolean qualifies,Direction direction,BigDecimal bodyRatio,BigDecimal rangeRatio,BigDecimal closeLocation){} }
